"use client";

/**
 * Type line: a line types itself out behind a caret, then its ending changes.
 * The ending is deleted and retyped, selected and typed over, or morphed one
 * letter at a time into the new words.
 *
 * Written by Better Design. Painted from the theme prop, so the line takes the
 * product's ink and the new ending and the selection take its primary colour.
 */
import { loadFont } from "@remotion/google-fonts/JetBrainsMono";
import type { ReactNode } from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from "remotion";
import { Caret, easings, pickFont, progress, type VideoTheme, useVideoTheme } from "@/lib/bd-video";

const { fontFamily: MONO } = loadFont("normal", { weights: ["500"], subsets: ["latin"] });

/** How the ending changes. */
export type TypeLineVariant = "rewrite" | "select" | "morph";

export interface TypeLineProps {
  /** The line as it first types out. */
  text?: string;
  /** The new ending that replaces the last `replace` words of `text`. */
  ending?: string;
  /** How many words at the end of `text` get replaced. */
  replace?: number;
  /** `rewrite` deletes and retypes, `select` selects and types over, `morph` turns letters into new ones. */
  variant?: TypeLineVariant;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then JetBrains Mono. */
  font?: string;
}

const TYPE_AT = 8;
const TYPE_RATE = 24;
const HOLD = 16;
const DELETE_RATE = 34;
const SELECT_RATE = 30;
const RETYPE_RATE = 20;
const MORPH_GAP = 2.4;
const MORPH_FRAMES = 12;

/** Type a line, then change how it ends. */
export function TypeLine({
  text = "Ship a launch film in a week",
  ending = "an afternoon",
  replace = 2,
  variant = "rewrite",
  theme: themeOverride,
  font,
}: TypeLineProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const family = pickFont(font, theme, MONO);

  const words = text.split(" ");
  const cut = Math.max(0, words.length - Math.max(1, replace));
  const stem = words.slice(0, cut).join(" ") + (cut > 0 ? " " : "");
  const oldEnd = words.slice(cut).join(" ");
  const longest = Math.max(text.length, stem.length + ending.length);
  const size = Math.min(96, Math.round(1600 / (longest * 0.6)));

  const typedCount = Math.max(0, Math.min(text.length, Math.floor(((frame - TYPE_AT) / fps) * TYPE_RATE)));
  const changeAt = TYPE_AT + (text.length / TYPE_RATE) * fps + HOLD;
  const typing = frame >= TYPE_AT && typedCount < text.length;

  let line: ReactNode = text.slice(0, typedCount);
  let solid = typing;
  let caretFirst = false;

  if (frame >= changeAt && variant === "rewrite") {
    const gone = Math.min(oldEnd.length, Math.floor(((frame - changeAt) / fps) * DELETE_RATE));
    const retypeAt = changeAt + (oldEnd.length / DELETE_RATE) * fps + 8;
    const added = Math.max(0, Math.min(ending.length, Math.floor(((frame - retypeAt) / fps) * RETYPE_RATE)));
    solid = frame < retypeAt + (ending.length / RETYPE_RATE) * fps;
    line = (
      <>
        {stem}
        {oldEnd.slice(0, oldEnd.length - gone)}
        <span style={{ color: theme.primary }}>{ending.slice(0, added)}</span>
      </>
    );
  } else if (frame >= changeAt && variant === "select") {
    const picked = Math.min(oldEnd.length, Math.floor(((frame - changeAt) / fps) * SELECT_RATE));
    const retypeAt = changeAt + (oldEnd.length / SELECT_RATE) * fps + 14;
    const added = Math.max(0, Math.min(ending.length, Math.floor(((frame - retypeAt) / fps) * RETYPE_RATE)));
    solid = frame < retypeAt + (ending.length / RETYPE_RATE) * fps;
    const kept = oldEnd.slice(0, oldEnd.length - picked);
    const chosen = oldEnd.slice(oldEnd.length - picked);
    if (added === 0) {
      caretFirst = picked > 0;
      line = (
        <>
          {stem}
          {kept}
          {caretFirst ? <Caret color={theme.primary} height={size * 1.05} solid /> : null}
          <span style={{ background: theme.primary, color: theme.primaryForeground, borderRadius: 4, boxShadow: `0 0 0 4px ${theme.primary}` }}>{chosen}</span>
        </>
      );
    } else {
      line = (
        <>
          {stem}
          <span style={{ color: theme.primary }}>{ending.slice(0, added)}</span>
        </>
      );
    }
  } else if (frame >= changeAt && variant === "morph") {
    const slots = Math.max(oldEnd.length, ending.length);
    solid = false;
    line = (
      <>
        {stem}
        {Array.from({ length: slots }, (_, j) => {
          const t = easings.out(progress(frame, changeAt + j * MORPH_GAP, MORPH_FRAMES));
          const from = oldEnd[j] ?? "";
          const to = ending[j] ?? "";
          const width = (from ? 1 : 0) + ((to ? 1 : 0) - (from ? 1 : 0)) * t;
          return (
            <span key={j} style={{ position: "relative", display: "inline-block", width: `${width * 0.6}em`, height: "1.2em", verticalAlign: "top" }}>
              <span style={{ position: "absolute", left: 0, opacity: 1 - t, transform: `translateY(${-t * 0.5}em)`, filter: `blur(${t * 6}px)` }}>{from}</span>
              <span
                style={{
                  position: "absolute",
                  left: 0,
                  opacity: t,
                  transform: `translateY(${(1 - t) * 0.5}em)`,
                  filter: `blur(${(1 - t) * 6}px)`,
                  color: theme.primary,
                }}
              >
                {to}
              </span>
            </span>
          );
        })}
      </>
    );
  }

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center", fontFamily: family }}>
      <div
        style={{
          width: `${longest * 0.6 + 0.4}em`,
          fontSize: size,
          fontWeight: 500,
          lineHeight: 1.2,
          color: theme.foreground,
          whiteSpace: "pre",
          display: "flex",
          alignItems: "center",
        }}
      >
        <span>{line}</span>
        {caretFirst ? null : <Caret color={theme.primary} height={size * 1.05} solid={solid} />}
      </div>
    </AbsoluteFill>
  );
}
